/**
 * The "Related blocks" sections on component pages are generated by
 * scripts/generate-block-backlinks.mjs from each block's "Components used"
 * list. The writing guide (apps/docs/WRITING.md) bans em dashes and Title
 * Case headings, so the generator must emit neither, and the committed
 * pages must match its output.
 */

import { execFileSync } from "node:child_process";
import { readdirSync, readFileSync } from "node:fs";
import { join, resolve } from "node:path";

import { describe, expect, it } from "vitest";

const ROOT = resolve(import.meta.dirname, "../../..");
const COMPONENTS = join(ROOT, "apps/docs/content/docs/components");
const START = "{/* backlinks:start */}";
const END = "{/* backlinks:end */}";

function generatedSections(): [string, string][] {
  return readdirSync(COMPONENTS)
    .filter((f) => f.endsWith(".mdx") && !f.startsWith("_"))
    .flatMap((file): [string, string][] => {
      const text = readFileSync(join(COMPONENTS, file), "utf8");
      const from = text.indexOf(START);
      return from === -1 ? [] : [[file, text.slice(from, text.indexOf(END))]];
    });
}

describe("generated Related blocks sections", () => {
  const sections = generatedSections();

  it("exist on at least one component page", () => {
    expect(sections.length).toBeGreaterThan(0);
  });

  it.each(sections)(
    "%s uses a sentence-case heading and no em dashes",
    (_file, section) => {
      expect(section).toContain("## Related blocks");
      expect(section).not.toContain("—");
    }
  );

  it("match the generator's output", () => {
    expect(() =>
      execFileSync(
        "node",
        ["scripts/generate-block-backlinks.mjs", "--check"],
        {
          cwd: ROOT,
          stdio: "pipe",
        }
      )
    ).not.toThrow();
  });
});
